{
  "name": "tmuxclihook",
  "version": "0.5.21",
  "description": "交互式 TUI 安装器：环境侦测、AI CLI 侦测、tmux-ai-status hooks 装/卸/修、TPM 软链校验",
  "type": "module",
  "bin": {
    "tmuxclihook": "bin/cli.js"
  },
  "files": [
    "bin",
    "src",
    "scripts",
    "tmux-ai-hooks-status.tmux",
    "README.md"
  ],
  "scripts": {
    "check": "for f in bin/cli.js src/*.js tools/*.js; do node --check \"$f\"; done && echo 'all js syntax OK'",
    "start": "node bin/cli.js",
    "test": "node --test",
    "prepack": "node tools/prepack-bundle.js",
    "postpack": "node tools/prepack-clean.js"
  },
  "engines": {
    "node": ">=18"
  },
  "dependencies": {
    "@clack/prompts": "^0.7.0",
    "execa": "^9.0.0",
    "picocolors": "^1.1.1"
  },
  "keywords": [
    "tmux",
    "claude-code",
    "codex",
    "opencode",
    "hooks",
    "installer",
    "tui"
  ],
  "author": "liu ziyuan",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/liuziyuan/tmux-claude-hooks-status",
    "directory": "installer"
  },
  "homepage": "https://github.com/liuziyuan/tmux-claude-hooks-status/tree/main/installer#readme",
  "bugs": {
    "url": "https://github.com/liuziyuan/tmux-claude-hooks-status/issues"
  },
  "publishConfig": {
    "access": "public",
    "provenance": true
  }
}
